log(`Equalising: ${underscrutinised.length}/${done.length} drew only one adversary`)
const equalised = await pipeline(underscrutinised,
  r => agent(advPrompt(r.c, 2, 9, ' You are the second adversary on a candidate whose first adversary rejected it, or whose Gate 2 graded novelty Low. You must NOT read the earlier adversary log and you are not told what it concluded. Any verdict already on this record is a prior finding, not one to inherit: the commonest error on this ledger is a real paper, quoted accurately, aimed at a different object than the candidate asks about. Check every nearest prior against the candidate\'s unit of analysis, endpoint, comparator and estimand, run all eight attacks on their merits, and choose Disguise vocabularies a first adversary would be least likely to have tried.'),
    { label: `adversary2:${r.c.id}`, phase: 'Equalise', schema: ADV_SCHEMA, effort: 'high' }),
  (adv, r) => agent(judgePrompt(r.c, [`${r.c.id}-adversary-1.md`, `${r.c.id}-adversary-2.md`]),
    { label: `rejudge2:${r.c.id}`, phase: 'Equalise', schema: JUDGE_SCHEMA }).then(j => ({ id: r.c.id, adv, judged: j })))
const equalisedIds = []
for (const x of equalised.filter(Boolean)) {
  const r = done.find(d => d.c.id === x.id)
  if (r && x.judged) { r.judged = x.judged; r.advs.push(x.adv) }
  equalisedIds.push(x.id)
}
rejected = done.filter(r => r.judged && r.judged.status === 'Rejected').length
log(`After equalising: ${rejected}/${done.length} rejected`)

let rerunIds = []
if (rejected < 3) {
  const survivors = done.filter(r => r.judged && r.judged.status !== 'Rejected')
  const rerun = await pipeline(survivors,
    r => agent(advPrompt(r.c, 3, 9, ' This is a HARDER rerun: the batch rejection rate was low, which suggests earlier adversaries were too gentle. Do not read the earlier adversary logs. Spend most effort on Disguise and Presupposition failure.'),
      { label: `adversary3:${r.c.id}`, phase: 'Rerun', schema: ADV_SCHEMA, model: 'fable', effort: 'max' }),
    (adv, r) => agent(judgePrompt(r.c, [`${r.c.id}-adversary-1.md`, `${r.c.id}-adversary-2.md`, `${r.c.id}-adversary-3.md`].filter((f, i) => i < r.advs.length || i === 2)),
      { label: `rejudge:${r.c.id}`, phase: 'Rerun', schema: JUDGE_SCHEMA }).then(j => ({ id: r.c.id, adv, judged: j })))
  for (const x of rerun.filter(Boolean)) {
    const r = done.find(d => d.c.id === x.id)
    if (r && x.judged) { r.judged = x.judged; r.advs.push(x.adv) }
    rerunIds.push(x.id)
  }
  rejected = done.filter(r => r.judged && r.judged.status === 'Rejected').length
  log(`After rerun: ${rejected}/${done.length} rejected`)
}

return {
  equalisedIds,
  rerunIds,
  candidates: done.map(r => ({
    id: r.c.id, source: r.c.source_method, domain: r.c.domain, question: r.c.question,
    novelty: r.res && r.res.novelty, nearest: r.res && r.res.nearest_prior, research_queries: r.res && r.res.query_count,
    adversaries: r.advs.filter(Boolean).map(a => `${a.verdict} (${a.disguise_queries_run} disguise q): ${a.statuses.map(s => s.status[0]).join('')}`),
    status: r.judged && r.judged.status, gate: r.judged && r.judged.gate,
    one_line: r.judged && r.judged.one_line, routing_row: r.judged && r.judged.routing_row,
  })),
}